contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amounts of base and quote to transfer into the vault before calling buyShares.
    // The test will transfer tokens by calling the public token contracts through the already-deployed C's _BASE_TOKEN_ and _QUOTE_TOKEN_
    // However, per constraints we may only call c's public surface. So we will rely on externally-visible balances by sending tokens
    // to c via its payable interface is not available; instead we simulate by assuming caller already has tokens and uses c.buyShares.
    // To keep the test self-contained and only use c's public surface, we simply call buyShares and observe shares and totalSupply changes.

    function run(address to) public payable {
        require(to != address(0), "to cannot be zero");

        // Read pre-state
        uint256 beforeShares = c.balanceOf(to);
        (, , uint256 beforeQuoteInput) = (uint256(0), uint256(0), uint256(0));
        uint256 beforeTotalSupply = c.totalSupply();

        // Try to call buyShares; it may revert if no base input or other conditions.
        bool reverted;
        uint256 sharesReturned;
        try c.buyShares(to) returns (uint256 shares, uint256 baseInput, uint256 quoteInput) {
            reverted = false;
            sharesReturned = shares;
        } catch {
            reverted = true;
            sharesReturned = 0;
        }

        // Read post-state (only via public getters)
        uint256 afterShares = c.balanceOf(to);
        uint256 afterTotalSupply = c.totalSupply();

        // General rule:
        // If buyShares did not revert then exactly `sharesReturned` were added to `to`'s balance
        // and totalSupply increased by `sharesReturned`.
        // We express as: not reverted -> (afterShares == beforeShares + sharesReturned && afterTotalSupply == beforeTotalSupply + sharesReturned)
        assert(reverted || (afterShares == beforeShares + sharesReturned && afterTotalSupply == beforeTotalSupply + sharesReturned));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to call sellShares: shareAmount to sell, recipient `to`, minimum amounts, data, and deadline.
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(to != address(0), "to nonzero");

        // Observe pre-state
        uint256 beforeShares = c.balanceOf(address(this));
        (uint256 baseReserveBefore, uint256 quoteReserveBefore) = c.getVaultReserve();
        uint256 totalBefore = c.totalSupply();

        // Ensure we have enough shares to attempt a meaningful call; if not, calling will revert and we still capture that.
        bool reverted;
        uint256 baseOut = 0;
        uint256 quoteOut = 0;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 baseAmount, uint256 quoteAmount) {
            reverted = false;
            baseOut = baseAmount;
            quoteOut = quoteAmount;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterShares = c.balanceOf(address(this));
        (uint256 baseReserveAfter, uint256 quoteReserveAfter) = c.getVaultReserve();
        uint256 totalAfter = c.totalSupply();

        // General rule to assert:
        // If call did not revert then
        // 1) this contract's share balance decreased by exactly shareAmount (i.e. beforeShares - afterShares == shareAmount)
        //    OR if shareAmount > beforeShares then call must have reverted (we require correctness across all inputs)
        // 2) the reserves reported by getVaultReserve after the call are each >= the tokens sent out (baseOut/quoteOut) subtracted from before reserves
        //    equivalently: baseReserveAfter + baseOut <= baseReserveBefore  and quoteReserveAfter + quoteOut <= quoteReserveBefore
        // 3) totalSupply decreased by shareAmount when successful
        // We express these as a single assert combining the implications.

        // Note: avoid underflow by rearranging comparisons.
        assert(
            reverted || (
                // caller had enough shares to sell
                beforeShares >= shareAmount
                // shares decreased by exactly shareAmount
                && (beforeShares - afterShares == shareAmount)
                // totalSupply decreased accordingly
                && (totalBefore - totalAfter == shareAmount)
                // reserves account for the amounts paid out (no more tokens disappeared than reported)
                && (baseReserveAfter + baseOut <= baseReserveBefore)
                && (quoteReserveAfter + quoteOut <= quoteReserveBefore)
            )
        );
    }

    // receive to accept any Ether if needed by calls (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(address to) public payable {
        require(to != address(0));

        // Observe totalSupply before
        uint256 totalBefore = c.totalSupply();

        // Call buyShares and capture returned values and whether it reverted
        bool reverted;
        uint256 shares;
        uint256 baseInput;
        uint256 quoteInput;
        try c.buyShares(to) returns (uint256 _shares, uint256 _baseInput, uint256 _quoteInput) {
            reverted = false;
            shares = _shares;
            baseInput = _baseInput;
            quoteInput = _quoteInput;
        } catch {
            reverted = true;
            shares = 0;
            baseInput = 0;
            quoteInput = 0;
        }

        // Observe totalSupply after
        uint256 totalAfter = c.totalSupply();

        // If the call succeeded (did not revert), then totalAfter == totalBefore + shares.
        // If it reverted, nothing else to assert about state (we only assert the general rule holds when the call succeeded).
        assert(reverted || totalAfter == totalBefore + shares);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(to != address(0));

        // Ensure the test contract has enough shares to attempt selling: mint some shares to this contract by simulating a buyShares call.
        // We cannot directly mint except via buyShares; prepare token balances by calling buyShares on c from this contract.
        // To keep this generic, first record caller's shares and totalSupply.
        uint256 beforeShares = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        // Try to call sellShares and observe whether it reverted. Per constraints, the call that mutates state must be top-level.
        bool reverted;
        uint256 baseAmount;
        uint256 quoteAmount;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 _baseAmount, uint256 _quoteAmount) {
            reverted = false;
            baseAmount = _baseAmount;
            quoteAmount = _quoteAmount;
        } catch {
            reverted = true;
            baseAmount = 0;
            quoteAmount = 0;
        }

        // Observe shares and totalSupply after the call (or attempted call)
        uint256 afterShares = c.balanceOf(address(this));
        uint256 totalAfter = c.totalSupply();

        // If the call succeeded (did not revert), then this contract's share balance decreased by exactly shareAmount
        // and totalSupply decreased by exactly shareAmount. If it reverted, no requirement.
        assert(reverted || (beforeShares == afterShares + shareAmount && totalBefore == totalAfter + shareAmount));
    }

    receive() external payable {}
}
